import subprocess, os, shutil, pathlib
def run(args, env):
    e=os.environ.copy(); e.update(env)
    r=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=3, env=e)
    print(args, env, r.returncode, repr(r.stdout[:200]), repr(r.stderr[:500]))
    for root,dirs,files in os.walk(list(env.values())[0] if env else "/tmp"):
        for f in files:
            p=os.path.join(root,f); print("  file",p, os.path.getsize(p), repr(open(p).read()[:500]))
        #break
for d in ["/tmp/cfg1","/tmp/cfg2","/tmp/cfg3","/tmp/cfg4"]:
    shutil.rmtree(d,ignore_errors=True)
run(["--print-config-dir"],{"XDG_CONFIG_HOME":"/tmp/cfg1"})
print("exists cfg1", os.path.exists("/tmp/cfg1"))
shutil.rmtree("/tmp/cfg2",ignore_errors=True)
run(["-v"],{"XDG_CONFIG_HOME":"/tmp/cfg2"})
print("exists cfg2", list(pathlib.Path("/tmp/cfg2").rglob("*")) if os.path.exists("/tmp/cfg2") else None)
run(["-c"],{"XDG_CONFIG_HOME":"/tmp/cfg3"})
print("cfg3", list(pathlib.Path("/tmp/cfg3").rglob("*")) if os.path.exists("/tmp/cfg3") else None)
# TUI via TERM missing will fail - does it create config/state?
run([],{"XDG_CONFIG_HOME":"/tmp/cfg4","XDG_STATE_HOME":"/tmp/state4","TERM":""})
for p in ["/tmp/cfg4","/tmp/state4"]:
    print(p, list(pathlib.Path(p).rglob("*")) if os.path.exists(p) else None)
    if os.path.exists(p):
        for f in pathlib.Path(p).rglob("*"):
            if f.is_file(): print(f, f.read_bytes()[:1000])
PY"}

