import subprocess,os,shutil
def cfg(val):
    os.makedirs("/tmp/nrcfg",exist_ok=True)
    open("/tmp/nrcfg/config.yml","w").write(f"notARepository: {val}\n")
def run(cwd="/tmp/notrepo2",input_data=""):
    try:
        r=subprocess.run(["/workspace/executable","-ucd","/tmp/nrcfg"],capture_output=True,text=True,timeout=3,cwd=cwd,input=input_data)
