            self.pos+=1
            # Child nested block following this item at deeper indent (for '-\\n  sub')
            item=_parse_inline(after,ln,self.total)
            node.value.append(item)
        return node

def parse_yaml(text):
    parser=_YamlParser(text)
    node=parser.parse()
    return node, parser.duplicates

def yaml_syntax_message(text):
    try:
        node,dups=parse_yaml(text)
        return None
    except YamlSyntaxError as e:
        return str(e)

