            raise YamlSyntaxError("yaml: did not find expected alphabetic or numeric character")
        return _scalar_type_and_value(parts[1], line_no, total_lines)
    if s.startswith("'") or s.startswith('"'):
        val,rest=_parse_quoted(s,line_no,total_lines)
        return (val,"str",s)
    low=s
    if low in ("true","True","TRUE"): return (True,"bool",s)
    if low in ("false","False","FALSE"): return (False,"bool",s)
    # timestamp
    if re.match(r'^\d{4}-\d{2}-\d{2}($|[Tt ])', s):
        return (s,"timestamp",s)
    # int (decimal, hex, octal, underscores)
    try:
        if re.match(r'^[+-]?\d[\d_]*$', s): return (int(s.replace('_',''),10),"int",s)
        if re.match(r'^[+-]?0x[0-9a-fA-F_]+$', s): return (int(s.replace('_',''),16),"int",s)
        if re.match(r'^[+-]?0o[0-7_]+$', s): return (int(s.replace('_','')[2:],8) if not s.lstrip('+-').startswith('0o') else int(s,8),"int",s)
    except Exception: pass
    if re.match(r'^[+-]?(\.\d+|\d+(\.\d*)?)([eE][+-]?\d+)?$', s) and (('.' in s) or ('e' in s.lower())):
        try: return (float(s),"float",s)
        except Exception: pass
    if s in (".inf",".Inf",".INF","+.inf","+.Inf","+.INF"): return (float('inf'),"float",s)
    if s in ("-.inf","-.Inf","-.INF"): return (float('-inf'),"float",s)
    if s in (".nan",".NaN",".NAN"): return (float('nan'),"float",s)
    return (s,"str",s)

def _parse_flow(s, line_no, total_lines):
    s=s.strip()
    if s.startswith("["):
        if not s.endswith("]"):
            # unclosed flow
            if s.count("[")>s.count("]"):
                raise YamlSyntaxError(f"yaml: line {line_no}: did not find expected ',' or ']'")
            raise YamlSyntaxError(f"yaml: line {line_no}: did not find expected node content")
        inner=s[1:-1].strip()
        node=YNode("seq",[],line_no,s)
        if inner=="": return node
        parts=[]; depth=0; in_s=False; in_d=False; start=0
        for i,ch in enumerate(inner):
            if in_s:
                if ch=="'": in_s=False
            elif in_d:
                if ch=='"' and inner[i-1]!='\\': in_d=False
            else:
                if ch=="'": in_s=True
                elif ch=='"': in_d=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==',' and depth==0:
                    parts.append(inner[start:i]); start=i+1
        parts.append(inner[start:])
        node.value=[_parse_inline(p.strip(),line_no,total_lines) for p in parts if p.strip()!='' or True]
        # filter trailing empty from trailing comma? keep simple: if last part empty remove
        if parts and parts[-1].strip()=="": node.value=node.value[:-1]
        return node
    if s.startswith("{"):
        if not s.endswith("}"):
            raise YamlSyntaxError(f"yaml: line {line_no}: did not find expected node content")
        inner=s[1:-1].strip()
        node=YNode("map",None,line_no,s); node.entries=[]
        if inner=="": return node
        parts=[]; depth=0; in_s=False; in_d=False; start=0
        for i,ch in enumerate(inner):
            if in_s:
                if ch=="'": in_s=False
            elif in_d:
                if ch=='"' and inner[i-1]!='\\': in_d=False
            else:
                if ch=="'": in_s=True
                elif ch=='"': in_d=True
                elif ch in '[{': depth+=1
                elif ch in ']}': depth-=1
                elif ch==',' and depth==0:
                    parts.append(inner[start:i]); start=i+1
        parts.append(inner[start:])
        for p in parts:
            p=p.strip()
            if not p: continue
            ci=_find_key_colon(p)
            if ci==-1:
                k=p; vnode=YNode("null",None,line_no)
            else:
                k=p[:ci].strip(); vnode=_parse_inline(p[ci+1:].strip(),line_no,total_lines)
            if (k.startswith("'") and k.endswith("'")) or (k.startswith('"') and k.endswith('"')):
                k=_parse_inline(k,line_no,total_lines).value
            node.entries.append((str(k),line_no,vnode)); node.key_lines[str(k)]=line_no
        return node
    # scalar
    val,typ,raw=_scalar_type_and_value(s,line_no,total_lines)
    if typ=="null": return YNode("null",None,line_no,s)
    n=YNode("scalar",val,line_no,s); n.raw=s; return n

def _parse_inline(s,line_no,total_lines):
    s=(s or "").strip()
    if s=="": return YNode("null",None,line_no)
    if s.startswith("[") or s.startswith("{"):
        return _parse_flow(s,line_no,total_lines)
    val,typ,raw=_scalar_type_and_value(s,line_no,total_lines)
    if typ=="null": return YNode("null",None,line_no,s)
    n=YNode("scalar",val,line_no,s); n.raw=s; return n

class _YamlParser:
    def __init__(self, text):
        self.orig_lines=text.splitlines()
        self.total=len(self.orig_lines)
        self.lines=[] # (indent, content, line_no, raw_line)
        for idx, raw in enumerate(self.orig_lines):
            ln=idx+1
            if raw.strip()=="" : continue
            # tab checks
            leading=raw[:len(raw)-len(raw.lstrip())]
            if '\t' in leading:
                if ln==1:
                    raise YamlSyntaxError("yaml: found character that cannot start any token")
                # if first non-whitespace preceded by tab at start
                if raw.startswith('\t') or raw.startswith(' \t'):
                    # Distinguish: earlier test line2 tab gave violates indentation
                    raise YamlSyntaxError(f"yaml: line {ln}: found a tab character that violates indentation")
                raise YamlSyntaxError(f"yaml: line {ln}: found character that cannot start any token")
            stripped=raw.lstrip(' ')
            if stripped.startswith('#'): continue
            content=_strip_yaml_comment(stripped).rstrip()
            if content=="": continue
            if content=="---":
                continue
            if content=="...":
                continue
            indent=len(raw)-len(stripped)
            self.lines.append([indent, content, ln, raw])
        self.pos=0
        self.duplicates=[] # (key, line, first_line)
    def parse(self):
        if not self.lines:
            return YNode("null",None,1)
        first=self.lines[0][1]
        if first.strip()==":":
            raise YamlSyntaxError("yaml: did not find expected key")
        node=self.parse_block(self.lines[0][0])
        if self.pos < len(self.lines):
            # leftover: likely bad indentation or scalar top with following mapping
            indent,content,ln,raw=self.lines[self.pos]
            if _find_key_colon(content)!=-1:
                raise YamlSyntaxError(f"yaml: line {ln}: mapping values are not allowed in this context")
            raise YamlSyntaxError(f"yaml: line {ln}: did not find expected node content")
        return node
    def parse_block(self, min_indent):
        if self.pos>=len(self.lines):
            return YNode("null",None,self.total)
        indent,content,ln,raw=self.lines[self.pos]
        if indent < min_indent:
            return YNode("null",None,ln)
        if content=="-" or content.startswith("- "):
            return self.parse_seq(indent)
        ci=_find_key_colon(content)
        if ci!=-1:
            return self.parse_map(indent)
        # scalar node (single line)
        self.pos+=1
        # flow unclosed detection
        if content.startswith("[") or content.startswith("{") or content.startswith("{{"):
            # inline parser will handle / raise node content for '{{'
            if content.startswith("{{"):
                raise YamlSyntaxError(f"yaml: line {ln}: did not find expected node content")
            return _parse_inline(content,ln,self.total)
        if content.startswith(":"):
            raise YamlSyntaxError("yaml: did not find expected key")
        return _parse_inline(content,ln,self.total)
    def parse_map(self, indent):
        node=YNode("map",None,self.lines[self.pos][2]); node.entries=[]
        seen={}
        while self.pos < len(self.lines):
            ind,content,ln,raw=self.lines[self.pos]
            if ind!=indent: break
            if content=="-" or content.startswith("- "): break
            ci=_find_key_colon(content)
            if ci==-1: break
            key_raw=content[:ci].strip()
            # key could be quoted
            if key_raw.startswith("'") or key_raw.startswith('"'):
                try: key=_parse_inline(key_raw,ln,self.total).value
                except Exception: key=key_raw
            else:
                key=key_raw
            key=str(key)
            rest=content[ci+1:].strip()
            if key in seen:
                self.duplicates.append((key,ln,seen[key]))
            else:
                seen[key]=ln
            node.key_lines[key]=ln
            self.pos+=1
            if rest=="":
                # child block
                if self.pos < len(self.lines):
                    nind,ncontent,nln,nraw=self.lines[self.pos]
                    if nind>indent:
                        val=self.parse_block(nind)
                    elif nind==indent and (ncontent=="-" or ncontent.startswith("- ")):
                        val=self.parse_seq(nind)
                    else:
                        val=YNode("null",None,ln)
                else:
                    val=YNode("null",None,ln)
            elif rest in ("|",">","|-",">-","|+",">+","|+",">+") or re.match(r'^[|>][+-]?\d*$',rest):
                val=self._parse_block_scalar(indent,rest,ln)
            else:
                # inline value; could be flow spanning? _parse_inline checks
                try:
                    val=_parse_inline(rest,ln,self.total)
                except YamlSyntaxError:
                    raise
                # If next line is more indented plain continuation for a plain scalar, ignore/join
                # (not common in configs)
            node.entries.append((key,ln,val))
        return node
    def _parse_block_scalar(self, parent_indent, indicator, ln):
        folded = indicator.startswith(">")
        collected=[]
        minind=None
        start_pos=self.pos
        while self.pos < len(self.lines):
            ind,content,nln,raw=self.lines[self.pos]
            if ind<=parent_indent: break
            if minind is None: minind=ind
            collected.append(raw[minind:] if len(raw)>=minind else content)
            self.pos+=1
        if folded:
            text=" ".join([c.strip() for c in collected]) + ("\n" if collected else "")
        else:
            text="\n".join(collected) + ("\n" if collected else "")
        n=YNode("scalar",text,ln); n.raw=text; return n
    def parse_seq(self, indent):
        node=YNode("seq",[],self.lines[self.pos][2])
        while self.pos < len(self.lines):
            ind,content,ln,raw=self.lines[self.pos]
            if ind!=indent: break
            if not (content=="-" or content.startswith("- ")): break
            if content=="-":
                self.pos+=1
                if self.pos < len(self.lines) and self.lines[self.pos][0]>indent:
                    item=self.parse_block(self.lines[self.pos][0])
                else:
                    item=YNode("null",None,ln)
                node.value.append(item); continue
            after=content[2:].lstrip()
            after_indent=ind+ (len(content)-len(after))
            ci=_find_key_colon(after)
            if ci!=-1:
                # map starting on same line: rewrite current line as a map line at after_indent
                self.lines[self.pos]=[after_indent, after, ln, raw]
                item=self.parse_map(after_indent)
                node.value.append(item); continue
            # scalar / flow
            self.pos+=1
            # Child nested block following this item at deeper indent (for '-\\n  sub')
            item=_parse_inline(after,ln,self.total)
            node.value.append(item)
        return node

def parse_yaml(text):
    parser=_YamlParser(text)
    node=parser.parse()
    return node, parser.duplicates

def yaml_syntax_message(text):
    try:
        node,dups=parse_yaml(text)
        return None
    except YamlSyntaxError as e:
        return str(e)

