        contexts=[c for c in _KB_CONTEXTS if c in kb] + [c for c in kb.keys() if c not in _KB_CONTEXTS]
        for ctx in contexts:
            sub=kb.get(ctx)
            if not isinstance(sub,dict): continue
            ctx_name=ctx[0].upper()+ctx[1:]
            # field order: use default config order if possible
            default_sub={}
