_MIGRATIONS=[("gui.skipUnstageLineWarning","gui.skipDiscardChangeWarning"),("keybinding.universal.executeCustomCommand","keybinding.universal.executeShellCommand")]
def apply_migrations(node, filepath, file_text):
    # returns possibly modified file text or None if file should be rewritten by text replacement
    changed_text=file_text
    for old,new in _MIGRATIONS:
        old_parts=old.split("."); new_parts=new.split(".")
        # navigate to parent of old
        cur=node; bad=False; missing=False
        for p in old_parts[:-1]:
            if cur.kind!="map":
                bad=True; break
            nxt=None
            for k,kl,v in cur.entries:
                if k==p: nxt=v; break
            if nxt is None:
                missing=True; break
            cur=nxt
        if bad:
            fatal_ts(f"Couldn't migrate config file at `{filepath}` for key {old}: yaml node in path is not a dictionary")
        if missing:
            continue
        if cur.kind!="map":
            fatal_ts(f"Couldn't migrate config file at `{filepath}` for key {old}: yaml node in path is not a dictionary")
        # check old exists
        old_entry=None; new_exists=False
        for k,kl,v in cur.entries:
            if k==old_parts[-1]: old_entry=(k,kl,v)
            if k==new_parts[-1]: new_exists=True
        if old_entry is None:
            continue
        if new_exists:
            fatal_ts(f"Couldn't migrate config file at `{filepath}` for key {old}: new key `{new_parts[-1]}' already exists")
        # rename in node
        new_entries=[]
        for k,kl,v in cur.entries:
            if k==old_parts[-1]: new_entries.append((new_parts[-1],kl,v))
            else: new_entries.append((k,kl,v))
        cur.entries=new_entries
        cur.key_lines[new_parts[-1]]=cur.key_lines.pop(old_parts[-1], old_entry[1])
        # textual replacement on the key line
        lines=changed_text.splitlines(True)
        li=old_entry[1]-1
        if 0 <= li < len(lines):
            # replace first occurrence of old leaf in that line
            lines[li]=lines[li].replace(old_parts[-1], new_parts[-1], 1)
            changed_text="".join(lines)
    if changed_text!=file_text:
        try:
            with open(filepath,"w",encoding="utf-8") as f: f.write(changed_text)
        except Exception as e:
            fatal_ts(str(e))
    return changed_text

