def deep_merge(base, override):
    if isinstance(base,dict) and isinstance(override,dict):
        out=dict(base)
        for k,v in override.items():
            if k in out:
                out[k]=deep_merge(out[k], v)
            else:
                out[k]=v
        return out
    # override replaces (including None -> keep as None? caller config getters treat None as missing-ish)
    return override

def config_get(cfg, path, default=None):
    cur=cfg
    for p in path.split("."):
        if not isinstance(cur,dict) or p not in cur: return default
        cur=cur[p]
    if cur is None:
        return default
    return cur

