def wrap_line(text,width, word_wrap=True):
    if width<=0: return [""]
    # expand tabs to 4
    text=str(text).expandtabs(4)
    if text=="": return [""]
    if not word_wrap:
        # hard wrap by columns
        res=[]; cur=""
        for ch in text:
            if char_width(cur+ch)>width:
                res.append(cur); cur=ch
            else: cur+=ch
        res.append(cur); return res
    # word wrap similar to textwrap but preserve leading spaces somewhat
    words=re.split(r'( )', text) # keep spaces as tokens
    # Use greedy wrapping by characters but prefer last space
    lines=[]; cur=""
    i=0
    # Simpler greedy char with last space tracking
    pos=0
    while pos < len(text):
        # if remaining fits
        if char_width(text[pos:])<=width:
            lines.append(text[pos:]); break
        # take width chars
        segment=text[pos:pos+width*2]
        # accumulate up to width columns
        end=pos; w=0; last_space=-1
        while end < len(text):
            ch=text[end]; cw=2 if unicodedata.east_asian_width(ch) in ('W','F') else 1
            if ch==' ': last_space=end
            if w+cw>width: break
            w+=cw; end+=1
        if end>=len(text):
            lines.append(text[pos:]); break
        if last_space>pos:
            lines.append(text[pos:last_space])
            pos=last_space+1
        else:
            lines.append(text[pos:end]); pos=end
    return lines if lines else [""]

