                txt=f"{f['status']} {f['path']}"
                items_raw.append({"display":[(txt,Style())],"plain":txt,"search":f["path"],"data":{"type":"file","file":{"path":f["path"],"x":f["status"],"y":" "},"path":f["path"],"commit_file":f}})
            return items_raw

