                lines.append("---"); lines.append("")
                lines.extend(self._branch_log_lines(t["name"]))
            else:
                lines=[f"Lightweight tag: {t['name']}","","---",""]
                lines.extend(self._branch_log_lines(t["name"]))
            return [("Tag", self._styled_plain(lines),None)]
        if ctx=="commits":
