        if ctx in ("reflog","subCommits"):
            if selected is None:
                title="Reflog Entry" if ctx=="reflog" else "Commit"
                return [(title, self._styled_plain(["No commits"]),None)]
            c=selected["data"]
            out=self.git_ok(["show","--stat","--decorate","--color=never",c["hash"]])
            title="Reflog Entry" if ctx=="reflog" else "Commit"
            return [(title, self._style_patch_lines(out.splitlines()),None)]
        if ctx=="stash":
