            s=selected["data"]
            out=self.git_ok(["stash","show","--stat","-p",s["ref"]])
            lines=[f"{s['ref']}: {s['message']}",""]
            if out.strip(): lines.extend(out.splitlines())
            return [("Stash", self._style_patch_lines(lines),None)]
        if ctx=="commitFiles":
            if selected is None: return [("Patch", self._styled_plain(["No files"]),None)]
            fdata=selected["data"]
            if fdata.get("type")=="dir":
                # diff of commit for dir path
                h=desc.get("hash","")
                path=fdata.get("path")
                if path=="/": path=""
                out=""
                # parents
                rc,rout,_=self.git(["rev-list","--parents","-n","1",h])
                parents=rout.split()[1:] if rc==0 and len(rout.split())>1 else []
                if parents:
                    out=self.git_ok(["diff",parents[0],h,"--",path] if path else ["diff",parents[0],h])
                else:
                    out=self.git_ok(["show","--format=",h,"--",path] if path else ["show","--format=",h])
                return [("Patch", self._style_diff_lines(out.splitlines()),None)]
            path=fdata.get("path","")
            h=desc.get("hash","")
            rc,rout,_=self.git(["rev-list","--parents","-n","1",h])
            parents=rout.split()[1:] if rc==0 and len(rout.split())>1 else []
            if parents:
                out=self.git_ok(["diff",parents[0],h,"--",path])
            else:
                out=self.git_ok(["show","--format=",h,"--",path])
            return [("Patch", self._style_diff_lines(out.splitlines()),None)]
        return [("Main", self._styled_plain([]),None)]

    def _style_patch_lines(self,lines):
        out=[]
        for l in lines:
            if l.startswith("diff --git") or l.startswith("index ") or l.startswith("---") or l.startswith("+++"):
                out.append([(l,Style(bold=True))])
            elif l.startswith("@@"):
                m=re.match(r'(@@[^@]*@@)(.*)',l)
                if m: out.append([(m.group(1),Style(fg="cyan")),(m.group(2),Style())])
                else: out.append([(l,Style(fg="cyan"))])
            elif l.startswith("+") and not l.startswith("+++"):
                out.append([(l,Style(fg="green"))])
            elif l.startswith("-") and not l.startswith("---"):
                out.append([(l,Style(fg="red"))])
            else:
                out.append([(l,Style())])
        return out

