    def _copy_to_clipboard(self,text):
        # try utilities in order xsel, xclip, wl-copy, pbcopy, termux
        candidates=[
            (["xsel","--clipboard","--input"],None),
            (["xclip","-selection","clipboard"],None),
            (["wl-copy"],None),
            (["pbcopy"],None),
            (["termux-clipboard-set"],None),
