    def _handle_context_key(self,token,desc):
        ctx=desc["context"]
        # status
        if ctx=="status":
            if token=="ENTER":
                self.open_recent_repos(); return
            if token=="e":
                self.suspend_requested=("edit_config",None); return
            if token=="o":
                # open config with xdg-open
                cfgfile=getattr(self,"config_file_for_edit",os.path.join(self.config_dir,"config.yml"))
                subprocess.Popen(["xdg-open",cfgfile],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); return
            if token=="u": return
            if token=="a":
                self.status_log_mode=not self.status_log_mode; return
            return
        if ctx=="files":
            self._files_key(token); return
        if ctx=="worktrees":
            self._worktrees_key(token); return
        if ctx=="submodules":
            self._submodules_key(token); return
        if ctx=="localBranches":
            self._branches_key(token); return
        if ctx=="remotes":
            self._remotes_key(token); return
        if ctx=="remoteBranches":
            self._remote_branches_key(token); return
        if ctx=="tags":
            self._tags_key(token); return
        if ctx in ("commits","reflog","subCommits"):
            self._commits_key(token,ctx); return
        if ctx=="stash":
            self._stash_key(token); return
        if ctx=="commitFiles":
            self._commit_files_key(token); return

    # ----- files -----
    def _files_key(self,token):
        desc,sel,items=self.selected()
        # global files keys regardless selection
        if token=="c":
            self._commit_action(no_verify=False); return
        if token=="w":
            self._commit_action(no_verify=True); return
        if token=="C":
            self.suspend_requested=("git_commit_editor",None); return
        if token=="A":
            self._amend_last(False); return
        if token=="s":
            self.push_prompt("Stash changes:","",on_confirm=lambda v: self.run_action_git("Stash changes",["stash","push","-m",v] if v else ["stash","push"]))
            return
        if token=="S":
            self._stash_options_menu(); return
        if token=="a":
            # toggle staged all
            files=self.data.get("files",[])
            any_unstaged=any((f["y"]!=" " or f["x"]=="?") for f in files)
            if any_unstaged:
                self.run_action_git("Stage all files",["add","-A"])
            else:
                self.run_action_git("Unstage all files",["reset","HEAD"])
            return
        if token=="D":
            self._files_reset_menu(); return
        if token=="f":
            self.run_action_git("Fetch",["fetch","--all"],show_output=True); return
        if token=="`":
            self.file_tree=not self.file_tree; return
        if token=="-":
            # collapse all
            for it in self.descriptor_items(desc):
                if it["data"].get("type")=="dir": self.file_collapsed.add(it["data"].get("path"))
            return
        if token=="=":
            self.file_collapsed.clear(); return
        if token=="CTRL_B":
            self._file_status_filter_menu(); return
        if token=="M":
            self.open_merge_rebase_menu(); return
        if sel is None: return
        data=sel["data"]
        if token==" ":
            self._toggle_stage_selected(sel); return
        if token=="ENTER":
            if data.get("type")=="dir":
                path=data.get("path")
                if path in self.file_collapsed: self.file_collapsed.remove(path)
                else: self.file_collapsed.add(path)
            else:
                self.focus_main=True
                # choose secondary
                f=data["file"]
                if f["x"] not in (" ","?") and f["y"]==" ": self.main_secondary="staged"
                else: self.main_secondary="unstaged"
            return
        if token=="e":
            if data.get("type")=="file": self.suspend_requested=("edit_file",data["file"]["path"])
            return
        if token=="o":
            if data.get("type")=="file":
                subprocess.Popen(["xdg-open",os.path.join(self.repo_root,data["file"]["path"])],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            return
        if token=="d":
            self._discard_menu(sel); return
        if token=="i":
            if data.get("type")=="file": self._ignore_menu(sel)
            return
