            if data.get("type")=="file": self.suspend_requested=("difftool",data["file"]["path"])
            return
        if token=="CTRL_F":
            return

    def _toggle_stage_selected(self,sel):
        data=sel["data"]
        if data.get("type")=="dir":
            path=data.get("path") or "."
            if path=="/": path="."
            # Determine if all staged under
            # If any file under has unstaged/untracked, stage; else unstage
            files=self._files_under(path)
            any_un=any((f["y"]!=" " or f["x"]=="?") for f in files)
            if any_un: self.run_action_git("Stage file",["add","--",path])
            else: self.run_action_git("Unstage file",["reset","HEAD","--",path])
            return
        f=data["file"]; path=f["path"]
        if f["x"]=="?" :
            self.run_action_git("Stage file",["add","--",path]); return
        if f["y"]!=" ":
            self.run_action_git("Stage file",["add","--",path]); return
        # only staged
        self.run_action_git("Unstage file",["reset","HEAD","--",path]); return
    def _files_under(self,path):
        if path in (".","/",""): return self.data.get("files",[])
        prefix=path.rstrip("/")+"/"
        return [f for f in self.data.get("files",[]) if f["path"]==path or f["path"].startswith(prefix)]

    def _commit_action(self,no_verify=False):
        files=self.data.get("files",[])
        staged=[f for f in files if f["x"] not in (" ","?")]
        if not staged:
            if config_get(self.cfg,"gui.skipNoStagedFilesWarning",False):
                self.run_action_git("Stage all files",["add","-A"])
                self.open_commit_editor(mode="commit",no_verify=no_verify)
            else:
                def confirm():
                    self.run_action_git("Stage all files",["add","-A"])
                    self.open_commit_editor(mode="commit",no_verify=no_verify)
                self.push_confirmation("No files staged","You have not staged any files. Commit all files?",on_confirm=confirm)
            return
        self.open_commit_editor(mode="commit",no_verify=no_verify)
    def _amend_last(self,from_commits_commit=None):
        if config_get(self.cfg,"gui.skipAmendWarning",False):
            self.run_action_git("Amend last commit",["commit","--amend","--no-edit"])
        else:
            self.push_confirmation("Amend last commit","Are you sure you want to amend last commit? Afterwards, you can change the commit message from the commits panel.",on_confirm=lambda: self.run_action_git("Amend last commit",["commit","--amend","--no-edit"]))

    def _stash_options_menu(self):
        def prompt_then(args_extra,label):
            self.push_prompt("Stash changes:","",on_confirm=lambda v: self.run_action_git(label,["stash","push"]+args_extra+(["-m",v] if v else [])))
        items=[
            {"key":"a","key_id":"a","label":"Stash all changes","action":lambda: prompt_then([],"Stash all changes")},
            {"key":"i","key_id":"i","label":"Stash all changes and keep index","action":lambda: prompt_then(["--keep-index"],"Stash all changes and keep index")},
            {"key":"U","key_id":"U","label":"Stash all changes including untracked files","action":lambda: prompt_then(["--include-untracked"],"Stash including untracked")},
            {"key":"s","key_id":"s","label":"Stash staged changes","action":lambda: prompt_then(["--staged"],"Stash staged changes")},
            {"key":"u","key_id":"u","label":"Stash unstaged changes","action":lambda: prompt_then(["--keep-index"],"Stash unstaged changes")},
            {"key":"","label":"Cancel","action":lambda: None},
        ]
        self.push_menu("Stash options",items)
    def _files_reset_menu(self):
        items=[
            {"key":"x","key_id":"x","label":"Nuke working tree","extra":"git reset --hard HEAD && git clean -fd","description":"If you want to make all the changes in the worktree go away, this is the way to do it. If there are dirty submodule changes this will stash those changes in the submodule(s).","action":lambda: self.push_confirmation("Nuke working tree","Are you sure you want to nuke the working tree? This will discard all changes in the worktree (staged, unstaged and untracked), which is not undoable.",on_confirm=self._nuke_worktree)},
            {"key":"u","key_id":"u","label":"Discard unstaged changes","extra":"git checkout -- .","action":lambda: self.run_action_git("Discard unstaged changes",["checkout","--","."])},
            {"key":"c","key_id":"c","label":"Discard untracked files","extra":"git clean -fd","action":lambda: self.run_action_git("Discard untracked files",["clean","-fd"])},
            {"key":"S","key_id":"S","label":"Discard staged changes","extra":"stash staged and drop stash","description":"This will create a new stash entry containing only staged files and then drop it, so that the working tree is left with only unstaged changes","action":self._discard_staged},
            {"key":"s","key_id":"s","label":"Soft reset","extra":"git reset --soft HEAD","action":lambda: self.run_action_git("Soft reset",["reset","--soft","HEAD"])},
            {"key":"m","key_id":"m","label":"mixed reset","extra":"git reset --mixed HEAD","action":lambda: self.run_action_git("Mixed reset",["reset","--mixed","HEAD"])},
            {"key":"h","key_id":"h","label":"Hard reset","extra":"git reset --hard HEAD","action":lambda: self.push_confirmation("Hard reset","Are you sure you want to do a hard reset? This will discard all uncommitted changes (both staged and unstaged), which is not undoable.",on_confirm=lambda: self.run_action_git("Hard reset",["reset","--hard","HEAD"]))},
            {"key":"","label":"Cancel","action":lambda: None},
        ]
        self.push_menu(None,items)
    def _nuke_worktree(self):
        rc1,o1,e1=self.git(["reset","--hard","HEAD"]); self.add_command_log("Nuke working tree",["git","reset","--hard","HEAD"])
        self.run_action_git("Nuke working tree",["clean","-fd"])
    def _discard_staged(self):
        # stash staged and drop
        rc,out,err=self.git(["stash","push","--staged","-m","lazygit-staged-discard"])
        self.add_command_log("Discard staged changes",["git","stash","push","--staged"])
        if rc==0:
            self.git(["stash","drop","stash@{0}"])
        else:
            if (err or out).strip(): self.push_error((err or out).strip())
        self.refresh()
    def _discard_menu(self,sel):
        data=sel["data"]
        if data.get("type")=="dir":
            path=data.get("path") or "."; name=path
            files=self._files_under(path)
        else:
            path=data.get("path"); name=path; files=[data["file"]]
        has_staged=any(f["x"] not in (" ","?") for f in files)
        has_unstaged=any(f["y"]!=" " or f["x"]=="?" for f in files)
        both=has_staged and has_unstaged
        def discard_all():
            # label 'Discard all changes in selected file(s)' command git checkout -- path (if untracked: clean)
            untracked=[f for f in files if f["x"]=="?"]
            tracked=[f for f in files if f["x"]!="?"]
            if tracked:
                self.run_action_git("Discard all changes in selected file(s)",["checkout","--",path])
                # also unstage tracked staged? checkout -- only worktree; if staged remains, need restore staged? Original x for a.txt only unstaged used checkout. For both, discard all should reset HEAD as well
                if has_staged:
                    self.git(["restore","--staged","--",path]); self.git(["checkout","--",path]); self.refresh()
            if untracked:
                for f in untracked:
                    try:
                        pth=os.path.join(self.repo_root,f["path"])
                        if os.path.isdir(pth) and not os.path.islink(pth): shutil.rmtree(pth)
                        elif os.path.exists(pth): os.remove(pth)
                    except Exception: pass
                self.refresh()
        def discard_unstaged():
            self.run_action_git("Discard unstaged changes",["checkout","--",path])
        def discard_staged():
            self.run_action_git("Discard staged changes",["restore","--staged","--",path])
        items=[]
        items.append({"key":"x","key_id":"x","label":"Discard all changes","description":f"Discard both staged and unstaged changes in '{name}'.","action":discard_all})
        u_disabled=None if both else "The selected items don't have both staged and unstaged changes."
        items.append({"key":"u","key_id":"u","label":"Discard unstaged changes","description":f"Discard unstaged changes in '{name}'.","disabled":bool(u_disabled),"disabled_reason":u_disabled,"action":discard_unstaged})
        if has_staged:
            s_disabled=None if both else "The selected items don't have both staged and unstaged changes."
            items.append({"key":"s","key_id":"s","label":"Discard staged changes","description":f"Discard staged changes in '{name}'.","disabled":bool(s_disabled),"disabled_reason":s_disabled,"action":discard_staged})
        items.append({"key":"","label":"Cancel","action":lambda: None})
        self.push_menu("Discard changes",items)
    def _ignore_menu(self,sel):
        f=sel["data"]["file"]; path=f["path"]; tracked=f["x"]!="?"
        def do_ignore(location):
            def really():
                target=os.path.join(self.repo_root,".gitignore") if location=="gitignore" else os.path.join(self.git_dir_abs or os.path.join(self.repo_root,".git"),"info","exclude")
                try:
                    os.makedirs(os.path.dirname(target),exist_ok=True)
                    with open(target,"a",encoding="utf-8") as fh: fh.write(f"/{path}\n")
                except Exception as e: self.push_error(str(e)); return
                self.refresh()
            if tracked:
                title="Ignore tracked file" if location=="gitignore" else "Exclude tracked file"
                self.push_confirmation(title,"Are you sure you want to ignore a tracked file?" if location=="gitignore" else "Are you sure you want to exclude a tracked file?",on_confirm=really)
            else:
                really()
        items=[
            {"key":"i","key_id":"i","label":"Add to .gitignore","action":lambda: do_ignore("gitignore")},
            {"key":"e","key_id":"e","label":"Add to .git/info/exclude","action":lambda: do_ignore("exclude")},
            {"key":"","label":"Cancel","action":lambda: None},
        ]
        self.push_menu("Ignore or exclude file",items)
    def _file_status_filter_menu(self):
        cur=getattr(self,"file_status_filter",None)
        def item(key,mode,label):
            mark="•" if cur==mode else " "
            return {"key":key,"key_id":key,"label":f"({mark}) {label}","action":lambda m=mode: setattr(self,"file_status_filter",m) or self.refresh()}
        items=[
            item("s","staged","Show only staged files"),
            item("u","unstaged","Show only unstaged files"),
            item("t","tracked","Show only tracked files"),
            item("T","untracked","Show only untracked files"),
            item("r",None,"No filter"),
            {"key":"","label":"Cancel","action":lambda: None},
        ]
        # remove duplicate Cancel label? original has '      Cancel' with spaces - our format will be two spaces
        self.push_menu("Filtering",items)
    def _upstream_reset_menu(self):
        # for current branch
        up=self.data.get("upstream") or ""
        items=[]
        if up:
            items.append({"key":"g","key_id":"g","label":"Reset to upstream","extra":f"reset --hard {up}","action":lambda: self.push_confirmation("Reset to upstream",f"Are you sure you want to reset to {up}?",on_confirm=lambda: self.run_action_git("Reset to upstream",["reset","--hard",up]))})
        items.append({"key":"","label":"Cancel","action":lambda: None})
        if len(items)>1: self.push_menu("Upstream options",items)
    def _files_copy_menu(self,sel):
        data=sel["data"]
        if data.get("type")!="file": return
        f=data["file"]; path=f["path"]
        def copy_text(txt):
            if self._copy_to_clipboard(txt): self.add_command_log_simple("Copy to clipboard",f"  Copying '{os.path.basename(txt) if False else txt}' to clipboard")
        items=[
            {"key":"n","key_id":"n","label":"File name","action":lambda: copy_text(os.path.basename(path))},
            {"key":"p","key_id":"p","label":"Relative path","action":lambda: copy_text(path)},
            {"key":"P","key_id":"P","label":"Absolute path","action":lambda: copy_text(os.path.join(self.repo_root,path))},
            {"key":"s","key_id":"s","label":"Diff of selected file","action":lambda: copy_text("\n".join(self._git_diff_for_path(path,False)))},
            {"key":"a","key_id":"a","label":"Diff of all files","action":lambda: copy_text("\n".join(self._git_diff_for_path(".",False)))},
            {"key":"","label":"Cancel","action":lambda: None},
        ]
        self.push_menu("Copy to clipboard",items)

