def key_id_from_config(v):
    if v is None: return None
    if not isinstance(v,str): return None
    if v=="": return None
    if v=="<disabled>": return None
    if len(v)==1:
        if v==" ": return "SPACE"
        return v
    special={
        "<space>":"SPACE","<enter>":"ENTER","<esc>":"ESC","<tab>":"TAB","<backtab>":"BACKTAB",
        "<up>":"UP","<down>":"DOWN","<left>":"LEFT","<right>":"RIGHT","<home>":"HOME","<end>":"END",
        "<pgup>":"PGUP","<pgdown>":"PGDN","<pgdn>":"PGDN","<delete>":"DELETE","<insert>":"INSERT","<backspace>":"BACKSPACE",
        "<s-up>":"SHIFT_UP","<s-down>":"SHIFT_DOWN","<a-enter>":"ALT_ENTER",
    }
    if v in special: return special[v]
    m=re.match(r'<c-(.)>',v)
    if m:
        ch=m.group(1)
        if ch=="/": return "CTRL_/"
        if ch==" ": return "CTRL_SPACE"
        return "CTRL_"+ch.upper()
    m=re.match(r'<f(\d+)>',v)
    if m: return "F"+m.group(1)
    if v=="<c-space>": return "CTRL_SPACE"
    return v

