        elif b<32:
            tokens.append("CTRL_"+chr(64+b)); i+=1; continue
        else:
            # utf8 char: determine length
            if b>=0xf0: ln=4
            elif b>=0xe0: ln=3
            elif b>=0xc0: ln=2
            else: ln=1
            if i+ln>len(data):
