        sys.stdout.write(config_dir+"\n")
        return 0
    if vals.get("logs"):
        state_dir=get_state_dir(config_dir,config_is_custom)
        tail_logs(os.path.join(state_dir,"development.log"))
        return 0
    # config files
    ucf=vals.get("use_config_file","")
    custom_files=None
    if ucf:
        custom_files=ucf.split(",")
    elif os.environ.get("LG_CONFIG_FILE"):
        custom_files=os.environ.get("LG_CONFIG_FILE").split(",")
    cfg=__import__("copy").deepcopy(DEFAULT_CONFIG)
    if custom_files is not None:
        for f in custom_files:
            d=load_config_file(f,"custom")
            if d is not None: cfg=deep_merge(cfg,d)
    else:
        cfg_file=os.path.join(config_dir,"config.yml")
        old_file=get_old_config_file(config_dir,config_is_custom)
        loaded_any=False
        if os.path.exists(cfg_file):
            d=load_config_file(cfg_file,"default")
            if d is not None: cfg=deep_merge(cfg,d); loaded_any=True
        if old_file and os.path.exists(old_file):
            d=load_config_file(old_file,"default")
            if d is not None: cfg=deep_merge(cfg,d); loaded_any=True
        # ensure directories & file after successful loads
        mkdir_all_go(config_dir)
        state_dir_tmp=get_state_dir(config_dir,config_is_custom)
        if state_dir_tmp!=config_dir: mkdir_all_go(state_dir_tmp)
        if not loaded_any and not os.path.exists(cfg_file):
            try:
                open(cfg_file,"a").close()
            except OSError as e:
                fatal_ts(f"open {cfg_file}: {e.strerror}")
    if custom_files is not None:
        mkdir_all_go(config_dir)
        state_dir_tmp=get_state_dir(config_dir,config_is_custom)
        if state_dir_tmp!=config_dir: mkdir_all_go(state_dir_tmp)
    state_dir=get_state_dir(config_dir,config_is_custom)
    state=load_state(state_dir)
    # debug logger
    if vals.get("debug"):
        DEBUG_LOGGER=DebugLogger(os.path.join(state_dir,"development.log"), os.environ.get("LOG_LEVEL",""))
    # validate git arg
    if cli.git_arg_set and cli.git_arg not in ("status","branch","log","stash"):
        fatal_ts(f"Invalid git arg value: '{cli.git_arg}'. Must be one of the following values: status, branch, log, stash. e.g. 'lazygit status'. See 'lazygit --help'.")
    # git env
    git_env={}
    if gitdir_arg:
        git_env["GIT_DIR"]=gitdir_arg
    # initial git commands (logged)
    run_cmd(["git","--version"],log_debug=True)
    rc,out,err=repo_paths_command(effective_dir,git_env)
    repo_paths=parse_repo_paths(out) if rc==0 else {}
    candidate=is_repo_candidate(effective_dir,gitdir_arg)
    # helpers for recent repo selection
    def choose_recent():
        for cand_path in state.recentrepos:
            if not os.path.isdir(cand_path): continue
            # must be a repo candidate/top
            r=subprocess.run(["git","-C",cand_path,"rev-parse","--show-toplevel"],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
            if r.returncode==0:
                return cand_path
        return None
    if not candidate:
        mode=config_get(cfg,"notARepository","prompt")
        if mode not in ("prompt","create","skip","quit"):
            fatal_plain("The value of 'notARepository' is incorrect. It should be one of 'prompt', 'create', 'skip', or 'quit'.")
        if mode=="quit":
            fatal_plain("Error: must be run inside a git repository")
        elif mode=="create":
            disp=format_cmd_display(["git","init"])
            rc2,o2,e2=run_cmd(["git","init"],cwd=effective_dir,log_debug=True,display=disp)
            if rc2!=0:
                wrapped_error("errors.errorString",(e2 or o2).strip(),GIT_INIT_STACK)
            rc,out,err=repo_paths_command(effective_dir,git_env); repo_paths=parse_repo_paths(out) if rc==0 else {}
        elif mode=="skip":
            chosen=choose_recent()
            if not chosen:
                fatal_plain("Must open lazygit in a git repository. No valid recent repositories. Exiting.")
            effective_dir=chosen; git_env={}
            try: os.chdir(chosen)
            except Exception: pass
            rc,out,err=repo_paths_command(effective_dir,git_env); repo_paths=parse_repo_paths(out) if rc==0 else {}
        else: # prompt
            sys.stdout.write("Not in a git repository. Create a new git repository? (y/N): "); sys.stdout.flush()
            ans=read_prompt_line()
            if ans.strip()=="y":
                sys.stdout.write("Branch name? (leave empty for git's default): "); sys.stdout.flush()
                branch=read_prompt_line().strip()
                args=["git","init"] if not branch else ["git","init",f"--initial-branch={branch}"]
                disp=format_cmd_display(args)
                rc2,o2,e2=run_cmd(args,cwd=effective_dir,log_debug=True,display=disp)
                if rc2!=0:
                    wrapped_error("errors.errorString",(e2 or o2),GIT_INIT_STACK)
                rc,out,err=repo_paths_command(effective_dir,git_env); repo_paths=parse_repo_paths(out) if rc==0 else {}
            else:
                chosen=choose_recent()
                if not chosen:
                    # need stderr without timestamp but stdout prompt already
                    eprint("Must open lazygit in a git repository. No valid recent repositories. Exiting.\n")
                    return 1
                effective_dir=chosen; git_env={}
                try: os.chdir(chosen)
                except Exception: pass
                rc,out,err=repo_paths_command(effective_dir,git_env); repo_paths=parse_repo_paths(out) if rc==0 else {}
    # terminal check (TERM, /dev/tty)
    tty_fd=check_term_and_tty()
    # second repo paths (GUI)
    rc2,out2,err2=repo_paths_command(effective_dir,git_env)
    if rc2!=0:
        # close tty fd before printing
        try: os.close(tty_fd)
        except Exception: pass
        if "not a git repository" in err2:
            fatal_ts("Error: must be run inside a git repository")
        else:
            wrapped_error("errors.errorString",f"Error getting repo paths: 'git -C {effective_dir} rev-parse --path-format=absolute --show-toplevel --absolute-git-dir --git-common-dir --is-bare-repository --show-superproject-working-tree' failed: {err2}",REPO_PATHS_STACK)
    repo_paths=parse_repo_paths(out2)
    repo_root=repo_paths.get("toplevel") or effective_dir
    # repo configs
    try:
        gitdir_abs=repo_paths.get("gitdir","")
        parents=[]
        d=os.path.dirname(repo_root.rstrip("/"))
        chain=[]
        while True:
            chain.append(d)
            nd=os.path.dirname(d)
            if nd==d: break
            d=nd
        for anc in reversed(chain):
            cand=os.path.join(anc,".lazygit.yml")
            if os.path.exists(cand):
                cfg=load_repo_config_with_wrap(cand,cfg)
        if gitdir_abs:
            cand=os.path.join(gitdir_abs,"lazygit.yml")
            if os.path.exists(cand):
                cfg=load_repo_config_with_wrap(cand,cfg)
    except ConfigWrapError as e:
        try: os.close(tty_fd)
        except Exception: pass
        wrapped_error("fmt.wrapError",e.msg)
    # profile server
    prof_srv=None
    if vals.get("profile"):
        prof_srv=start_profile_server()
    # Create app
    app=LazygitApp(cli,cfg,state,config_dir,state_dir,effective_dir,repo_paths,git_env,tty_fd)
    # file to edit for status panel: if custom config files, first one? Original likely config file that is used (configDir/config.yml if no custom, else first custom?) Use configDir/config.yml default
    if custom_files:
        app.config_file_for_edit=custom_files[0]
    else:
        app.config_file_for_edit=os.path.join(config_dir,"config.yml")
    exit_code=0
    try:
        exit_code=run_tui(app)
    except KeyboardInterrupt:
        exit_code=1
    finally:
        app.save_state_now()
        # LAZYGIT_NEW_DIR_FILE
        ndfile=os.environ.get("LAZYGIT_NEW_DIR_FILE")
        if ndfile:
            target=orig_cwd if app.quit_without_dir else app.repo_root
            try:
                with open(ndfile,"w",encoding="utf-8") as f: f.write(target)
            except Exception: pass
        if DEBUG_LOGGER: DEBUG_LOGGER.close()
        try: os.close(tty_fd)
        except Exception: pass
    return exit_code

if __name__=="__main__":
    try:
        code=main()
    except SystemExit as e:
        code=e.code if isinstance(e.code,int) else (0 if e.code is None else 1)
    sys.exit(code if isinstance(code,int) else 0)
